<script lang="ts">
import {onMount} from 'svelte';import type {Catalog,Locale} from './locales';import Toggle from './components/Toggle.svelte';
let {t,locale,request,settings=false,backend='windows'}=$props<{t:Catalog;locale:Locale;request:(url:string,body?:object)=>Promise<any>;settings?:boolean;backend?:string}>();
type Info={enabled:boolean;active:boolean;connected:boolean;transport:string;health:string;phase:string;phaseDetail:string;buildCommit:string|null;tick:number|null;lastReply:string|null;startedAt:string|null;lastExit:string|null;lastExitCode:number|null;restartRequired:boolean;settings:{enabled:boolean;port:number;retentionDays:number;maxMegabytes:number}};
let info=$state<Info|null>(null),enabled=$state(false),port=$state(20774),days=$state(7),size=$state(100),busy=$state(false),error=$state(''),pollError=$state(''),saved=$state(false),loaded=$state(false);let dialog=$state<HTMLDialogElement>()!;
let format=(value:string|null)=>value?new Date(value).toLocaleString(locale):'—';
let health=$derived(info?.health==='alive'?t.bridgeAlive:info?.health==='stalled'?t.bridgeStalled:info?.health==='frozen'?t.bridgeFrozen:info?.health==='dead'?t.bridgeDead:t.bridgeUnknown);
let phase=$derived(info?.phase==='starting'?t.bridgeStarting:info?.phase==='active'?t.bridgeReady:t.bridgeUnknown);
async function load(){try{info=await request('/api/bridge');pollError='';if(!loaded){enabled=info!.settings.enabled;port=info!.settings.port;days=info!.settings.retentionDays;size=info!.settings.maxMegabytes;loaded=true;}}catch(e){pollError=(e as Error).message;}}
async function save(){busy=true;error='';saved=false;try{await request('/api/bridge/settings',{enabled,port,retentionDays:days,maxMegabytes:size});saved=true;await load();}catch(e){error=(e as Error).message;}finally{busy=false;}}
onMount(()=>{load();const timer=setInterval(load,2000);return()=>clearInterval(timer);});
</script>
{#if settings}
<section class="update-panel bridge-settings"><h2>{t.bridgeTitle}</h2>{#if info?.restartRequired}<p class="update-status" role="status">{t.bridgePending}</p>{/if}<p class="muted">{t.bridgeHint}</p><Toggle checked={enabled} label={t.bridgeEnable} disabled={busy} onchange={v=>{enabled=v;saved=false;}}/><div class="bridge-fields"><label>{t.bridgePort}<input type="number" min="1024" max="65535" bind:value={port} disabled={busy}/></label><label>{t.retentionDays}<input type="number" min="1" max="30" bind:value={days} disabled={busy}/></label><label>{t.retentionSize}<input type="number" min="10" max="1000" bind:value={size} disabled={busy}/></label></div>{#if backend==='docker'}<p class="muted">{t.bridgeDockerHint}</p>{/if}<button disabled={busy||!loaded||!Number.isInteger(port)||port<1024||port>65535||!Number.isInteger(days)||days<1||days>30||!Number.isInteger(size)||size<10||size>1000} onclick={()=>dialog.showModal()}>{t.saveBridge}</button>{#if saved}<p class="notice" role="status">{t.bridgeSaved}</p>{/if}{#if error||pollError}<p class="error" role="alert">{t.errors[(error||pollError) as keyof typeof t.errors]??t.errors['request.failed']}</p>{/if}</section>
<dialog bind:this={dialog} aria-labelledby="bridge-confirm"><h2 id="bridge-confirm">{t.bridgeConfirm}</h2><p>{t.bridgeHint}</p>{#if backend==='docker'}<p>{t.bridgeDockerHint}</p>{/if}<div class="actions"><button onclick={()=>dialog.close()}>{t.cancel}</button><button class="primary" onclick={()=>{dialog.close();save();}}>{t.saveBridge}</button></div></dialog>
{:else}
<section class="bridge-summary" aria-label={t.bridgeTitle}><h2>{t.bridgeTitle}</h2><dl><dt>{t.bridgeActive}</dt><dd>{info?.connected?t.bridgeConnected:info?.active?t.bridgeFallback:'PTY'}</dd><dt>{t.bridgeHealth}</dt><dd class:online={info?.health==='alive'}>{health}</dd><dt>{t.bridgePhase}</dt><dd>{phase}</dd><dt>{t.bridgeCommit}</dt><dd class="path">{info?.buildCommit??'—'}</dd><dt>{t.bridgeTick}</dt><dd>{info?.tick??'—'}</dd><dt>{t.bridgeLastReply}</dt><dd>{format(info?.lastReply??null)}</dd><dt>{t.bridgeUptime}</dt><dd>{format(info?.startedAt??null)}</dd><dt>{t.bridgeLastExit}</dt><dd>{format(info?.lastExit??null)}{#if info?.lastExitCode!=null} · {info.lastExitCode}{/if}</dd></dl>{#if info?.restartRequired}<p role="status" class="muted">{t.bridgePending}</p>{/if}{#if error||pollError}<p class="error" role="alert">{t.errors[(error||pollError) as keyof typeof t.errors]??t.errors['request.failed']}</p>{/if}</section>
{/if}
